CREATE TABLE review_candidates(id text PRIMARY KEY,source_number integer NOT NULL,occurrence integer NOT NULL DEFAULT 1,legacy_slug text UNIQUE REFERENCES cms_pages(slug),text_truncated boolean NOT NULL DEFAULT false,original_text text NOT NULL DEFAULT '',transcription text NOT NULL DEFAULT '',reviewer text NOT NULL DEFAULT 'Client Review',rating numeric CHECK(rating BETWEEN 0 AND 5),platform text NOT NULL DEFAULT '',platform_verified boolean NOT NULL DEFAULT false,review_date text NOT NULL DEFAULT '',category text NOT NULL DEFAULT 'Engineering',project_slug text NOT NULL DEFAULT '',service_slug text NOT NULL DEFAULT '',duplicate_of text REFERENCES review_candidates(id),privacy text NOT NULL DEFAULT 'needs_review' CHECK(privacy IN('needs_review','cleared','restricted')),clearance_note text NOT NULL DEFAULT '',confidence text NOT NULL DEFAULT 'unverified',featured boolean NOT NULL DEFAULT false,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','approved','published','archived','excluded')),revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
